// Plan, write, check and stage the generated files:
//   releases/vX.Y.Z/index.html   (from templates/release.html + content.json)
//   releases.json                (authored fields kept; "derived" fields recomputed; newest first)
//   shared header/head/footer regions inside index.html and releases/index.html
import fs from 'node:fs';
import path from 'node:path';
import { clearFsCache, existsExact, norm, readText, toPosix, writeIfChanged } from './util.mjs';
import { derive, loadProject, serializeEntry, sortedRecords } from './model.mjs';
import { renderReleasePage, renderRobots, renderSitemap, syncRegions } from './render.mjs';

const SHELLS = ['index.html', 'releases/index.html', 'admin/index.html'];
const OPTIONAL_SHELLS = new Set(['admin/index.html']); // the manual composer: delete the admin/ folder to remove it
const NOTE = 'Source of truth for release metadata. Edit authored fields (version, date, type, status, featured, sample, title, summary, tags) freely; "derived" is regenerated by `node tools/rn.mjs build`, so do not edit it by hand.';

export function loadTemplates(root) {
  const partialsDir = path.join(root, 'templates', 'partials');
  const partials = {};
  for (const f of fs.readdirSync(partialsDir)) if (f.endsWith('.html')) partials[f.slice(0, -5)] = readText(path.join(partialsDir, f));
  return { template: readText(path.join(root, 'templates', 'release.html')), partials };
}

/** Compute every generated file in memory. Nothing is written here. */
export function computeOutputs(project) {
  const { root, report, data } = project;
  const files = new Map();
  const { template, partials } = loadTemplates(root);
  const recs = sortedRecords(project);

  for (const rec of recs) {
    if (!rec.valid) continue;
    rec.derived = rec.content ? derive(project, rec) : rec.entry.derived;
    if (!rec.custom) files.set(`${rec.dir}/index.html`, renderReleasePage({ project, rec, template, partials }));
  }

  const out = {
    _note: NOTE,
    product: data.product || 'RevGen-i',
    schemaVersion: 1,
    site: { url: data.site?.url ?? '', noindex: data.site?.noindex === true },
    releases: recs.map((r) => serializeEntry(r.entry, r.derived)),
  };
  files.set('releases.json', `${JSON.stringify(out, null, 2)}\n`);

  for (const rel of SHELLS) {
    const abs = path.join(root, rel);
    if (!fs.existsSync(abs)) { if (!OPTIONAL_SHELLS.has(rel)) report.err(rel, 'shell page is missing.'); continue; }
    const depth = rel.split('/').length - 1;
    files.set(rel, syncRegions(readText(abs), partials, depth ? '../'.repeat(depth) : './'));
  }
  return files;
}

export function writeOutputs(root, files) {
  const written = [];
  for (const [rel, content] of files) if (writeIfChanged(path.join(root, rel), content)) written.push(rel);
  return written;
}

export function staleOutputs(root, files) {
  const stale = [];
  for (const [rel, content] of files) {
    const abs = path.join(root, rel);
    if (!fs.existsSync(abs) || norm(readText(abs)) !== norm(content)) stale.push(rel);
  }
  return stale;
}

/** Every relative href/src in the generated pages must resolve (exact capitalisation, like GitHub Pages). */
export function checkLinks(project, files) {
  const { root, report } = project;
  clearFsCache();
  const htmlOf = (rel) => files.get(rel) ?? (existsExact(root, rel) && rel.endsWith('.html') ? readText(path.join(root, rel)) : null);
  const exists = (rel) => files.has(rel) || existsExact(root, rel);
  const idCache = new Map();
  const idsOf = (rel) => {
    if (!idCache.has(rel)) idCache.set(rel, new Set([...(htmlOf(rel) ?? '').matchAll(/\sid="([^"]+)"/g)].map((m) => m[1])));
    return idCache.get(rel);
  };
  const seen = new Set();
  for (const [rel, html] of files) {
    if (!rel.endsWith('.html')) continue;
    const dir = path.posix.dirname(rel);
    for (const m of html.matchAll(/\s(?:href|src)="([^"]*)"/g)) {
      const ref = m[1].replace(/&amp;/g, '&');
      if (!ref || /^(https?:|mailto:|tel:|data:|javascript:|\/\/)/i.test(ref)) continue;
      const key = `${rel}|${ref}`;
      if (seen.has(key)) continue;
      seen.add(key);
      const [pathPart, hash = ''] = ref.split('#');
      let target = rel;
      if (pathPart) {
        let p;
        try { p = decodeURI(pathPart.split('?')[0]); } catch { p = pathPart; }
        target = path.posix.normalize(path.posix.join(dir, p));
        if (target.startsWith('..')) { report.err(rel, `link leaves the site folder: "${ref}"`); continue; }
        if (p.endsWith('/') || target === '.' || target === '') target = path.posix.join(target, 'index.html');
      }
      if (!exists(target)) { report.err(rel, `broken link: "${ref}" -> ${target} not found (check the name and capitalisation).`); continue; }
      if (hash && target.endsWith('.html') && !idsOf(target).has(hash)) report.err(rel, `broken anchor: "${ref}" -> no element with id="${hash}" in ${target}.`);
    }
  }

  // url(...) references inside the stylesheets (fonts, icons) must resolve too, with exact capitalisation.
  const cssDir = path.join(root, 'assets', 'css');
  if (fs.existsSync(cssDir)) {
    for (const name of fs.readdirSync(cssDir).filter((n) => n.endsWith('.css'))) {
      const rel = `assets/css/${name}`;
      const css = readText(path.join(cssDir, name)).replace(/\/\*[\s\S]*?\*\//g, '');
      for (const m of css.matchAll(/url\(\s*["']?([^"')]+?)["']?\s*\)/g)) {
        const ref = m[1].trim();
        if (/^(https?:|data:|#|\/\/)/i.test(ref)) { if (/^(https?:|\/\/)/i.test(ref)) report.err(rel, `external resource "${ref}": the site must not load third-party files.`); continue; }
        const target = path.posix.normalize(path.posix.join('assets/css', ref.split(/[?#]/)[0]));
        if (target.startsWith('..') || !exists(target)) report.err(rel, `url(${ref}) -> ${target} not found (check the name and capitalisation).`);
      }
    }
  }
}

/** Load, validate, generate. `write:false` is a read-only check that reports stale generated files. */
export function runBuild(root, { write }) {
  const project = loadProject(root);
  let files = null, written = [], stale = [];
  if (!project.report.errors.length) {
    files = computeOutputs(project);
    if (!project.report.errors.length) {
      if (write) written = writeOutputs(root, files);
      else stale = staleOutputs(root, files);
      checkLinks(project, files);
    }
  }
  return { project, files, written, stale };
}

/* ------------------------------------------------------------------ staging for GitHub Pages */
const JUNK = new Set(['.DS_Store', 'Thumbs.db', 'desktop.ini']);
function copyTree(from, to, skip = () => false) {
  fs.mkdirSync(to, { recursive: true });
  for (const e of fs.readdirSync(from, { withFileTypes: true })) {
    if (JUNK.has(e.name) || skip(e)) continue;
    const a = path.join(from, e.name), b = path.join(to, e.name);
    if (e.isDirectory()) copyTree(a, b, skip); else fs.copyFileSync(a, b);
  }
}

/** Copy only what the public site needs. Drafts, source content, templates and tooling never leave the repo. */
export function stage(project, files, outDir) {
  const { root } = project;
  const out = path.resolve(outDir);
  const rel = path.relative(out, root);
  if (out === root || (!rel.startsWith('..') && !path.isAbsolute(rel)))
    throw new Error(`Refusing to stage into ${out}: it contains the source folder.`);
  if (fs.existsSync(out)) {
    // Only ever wipe a folder that is empty or is itself the output of a previous stage.
    const previousStage = ['index.html', 'releases.json', '.nojekyll'].every((f) => fs.existsSync(path.join(out, f)));
    if (fs.readdirSync(out).length && !previousStage)
      throw new Error(`Refusing to overwrite ${out}: it is not empty and does not look like staged output. Choose another --out folder.`);
    fs.rmSync(out, { recursive: true, force: true });
  }
  fs.mkdirSync(out, { recursive: true });

  const published = sortedRecords(project).filter((r) => r.entry.status === 'published');
  for (const f of SHELLS) {
    if (!fs.existsSync(path.join(root, f))) continue; // optional shells (the composer) may be absent
    fs.mkdirSync(path.dirname(path.join(out, f)), { recursive: true });
    fs.copyFileSync(path.join(root, f), path.join(out, f));
  }
  copyTree(path.join(root, 'assets'), path.join(out, 'assets'));
  if (fs.existsSync(path.join(root, 'admin'))) copyTree(path.join(root, 'admin'), path.join(out, 'admin')); // the manual release composer
  // A published release's content.json goes with it: the page's "Download PDF" reads it (it is the same content the page shows).
  for (const r of published) copyTree(path.join(root, r.dir), path.join(out, r.dir));

  const index = JSON.parse(files.get('releases.json'));
  index.releases = index.releases.filter((r) => r.status === 'published');
  fs.writeFileSync(path.join(out, 'releases.json'), `${JSON.stringify(index, null, 2)}\n`);
  fs.writeFileSync(path.join(out, '.nojekyll'), '');
  const site = project.data.site ?? {};
  if (site.url) {
    fs.writeFileSync(path.join(out, 'sitemap.xml'), renderSitemap(site, published));
    fs.writeFileSync(path.join(out, 'robots.txt'), renderRobots(site));
  }

  // Belt and braces: prove that no draft or source file leaked into the output. Only a published release's own content.json may be there.
  const leaks = [], publishedDirs = new Set(published.map((r) => r.dir));
  const walk = (d) => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else if (e.name === 'content.json') { const rel = toPosix(path.relative(out, p)); if (!publishedDirs.has(path.posix.dirname(rel))) leaks.push(rel); }
    }
  };
  walk(out);
  for (const r of project.releases) if (r.entry.status !== 'published' && fs.existsSync(path.join(out, r.dir))) leaks.push(r.dir);
  if (index.releases.some((r) => r.status !== 'published')) leaks.push('releases.json (draft entry)');
  if (leaks.length) throw new Error(`Staging leaked non-public files: ${leaks.join(', ')}`);
  return { out, published: published.length, excluded: project.releases.length - published.length };
}
